package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.nio.file.attribute.PosixFilePermissions;
import java.util.*;
import org.jlinalg.metagenomics.MaltExtractReadProjection;
import org.jlinalg.metagenomics.MaltExtractRmaReader;
import org.jlinalg.metagenomics.MaltExtractTaxonomy;

/** Complete native source1.7 read projection for explicitly supplied stored taxon IDs.
 * Name resolution/descendant discovery, destacking, deduplication, sampling and
 * upstream summary/damage statistics remain distinct operations.
 */
public final class MaltExtractReadsCli {
    private MaltExtractReadsCli() { }
    private static final String STATUS="complete-native-maltextract17-read-projection-only";
    private static final String METHOD="source17-complete-projection";
    private static final String ACTION="Required action: retain complete RMA6, taxonomy, explicit stored-taxon list, outputs and diagnostics. Supply the pinned GPL HOPS0.35 MaltExtract1.7.jar provider and a permitted JDK21 or JDK25. Install/download only where permitted; if unavailable or forbidden, skip this dependent extraction. Resolve the named input, identity, integrity or capacity issue before retrying a NEW output directory. Select stored classification IDs explicitly; this command does not discover descendants or reproduce the paper's unreported MaltExtract settings. Zero extracted reads do not establish biological absence.";
    private static final String WARNING="# Native MaltExtract1.7 read projection: scope and required actions\n\n"
        +"**This is the explicitly selected native complete-projection method.** Destacking, duplicate removal and downsampling are disabled. This differs from the stock MaltExtract1.7 filter settings and must be declared in downstream analyses. Whole MaltExtract/HOPS, original summary/damage statistics and biological paper reproduction remain incomplete.\n\n"
        +"Taxon IDs are literal stored classification groups. No name resolution, descendant discovery, taxonomic rollup or automatic expansion occurs. Supply the complete deliberately selected group list for the intended analysis; a parent group alone does not include reads stored in descendant groups.\n\n"
        +"RMA decoding uses the exact original1.7 embedded API with score1/expected100 and sequence retrieval. Native Java preserves the source first-score/float threshold, ancient ten-match cap, terminal lesion case/gap rules, concatenated read key and unusual complexity loop. No source bug or record is silently repaired. Native FASTA order is deterministic; equivalence is by complete literal header/sequence multisets, not original HashMap order. Empty projections are empty FASTA files.\n\n"
        +"The input's native accession-mapping provenance, when applicable, must be retained. Saved verification checks captured consistency and recomputes every projection; it does not authenticate the producer or repeat original MaltExtract execution. Complete input/capacity errors admit no result.\n\n"+ACTION+"\n";
    record Limits(long fileBytes,long inputBytes,int reads,long matches,int matchesPerRead,int textCharacters,int taxa) {
        MaltExtractRmaReader.Limits reader(){return new MaltExtractRmaReader.Limits(fileBytes,reads,matches,matchesPerRead,textCharacters,3000000);}
        Map<String,Object> document(){return Map.of("file_bytes",fileBytes,"input_bytes",inputBytes,"reads",reads,"matches",matches,"matches_per_read",matchesPerRead,"text_characters",textCharacters,"taxa",taxa);}
    }
    public static void main(String[] args){int code=run(args,System.out,System.err);if(code!=0)System.exit(code);}
    static int run(String[] args,PrintStream console,PrintStream error) {
        Path out=null;boolean owned=false;
        try {
            if(args.length==1&&args[0].equals("--help")){console.println("Native complete MaltExtract1.7 read projection\n--runtime ROOT_WITH_MaltExtract1.7.jar --input FILE.rma6 --taxonomy ncbi.tre --taxa TSV --mode default|ancient|both --method source17-complete-projection --input-provenance supplied|native-accession-alternative --out NEW_DIRECTORY\nTaxa TSV has the literal one-column header taxon_id and positive decimal stored classification IDs. Descendants are not discovered.\nOptions: --top-fraction 0.01 --minimum-identity-percent 0 --maximum-read-length 0 --minimum-complexity 0 --top-alignment-only false --single-stranded false. Destacking, deduplication and downsampling are disabled explicitly by this method.\nCapacities: --maximum-file-bytes 1000000000 --maximum-input-bytes 4000000000 --maximum-reads 1000000 --maximum-matches 10000000 --maximum-matches-per-read 100000 --maximum-text-characters 1000000 --maximum-taxa 1000. Complete populations are refused rather than truncated. Numeric taxonomy with retained finite branch lengths; capacity:100MB,3000000 nodes,depth1024.\nRead-only saved verification: --verify BUNDLE --runtime ROOT\n"+ACTION);return 0;}
            Set<String> allowed=Set.of("--runtime","--input","--taxonomy","--taxa","--mode","--method","--input-provenance","--out","--verify","--top-fraction","--minimum-identity-percent","--maximum-read-length","--minimum-complexity","--top-alignment-only","--single-stranded","--maximum-file-bytes","--maximum-input-bytes","--maximum-reads","--maximum-matches","--maximum-matches-per-read","--maximum-text-characters","--maximum-taxa");
            var options=new LinkedHashMap<String,String>();for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!allowed.contains(args[i])||options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require unique complete options; see --help");
            if(options.containsKey("--verify")){if(!options.keySet().equals(Set.of("--verify","--runtime")))throw new IOException("Saved verification requires --verify and --runtime only");verify(Path.of(options.get("--verify")).toRealPath(),Path.of(options.get("--runtime")));console.println("VERIFIED_COMPLETE_NATIVE_MALTEXTRACT17_READ_PROJECTION_ONLY\n"+ACTION);return 0;}
            if(!options.keySet().containsAll(Set.of("--runtime","--input","--taxonomy","--taxa","--mode","--method","--input-provenance","--out")))throw new IOException("Complete input, method, mode and provenance choices are required");
            if(!METHOD.equals(options.get("--method")))throw new IOException("Explicit source17-complete-projection method required");
            String provenance=options.get("--input-provenance");if(!Set.of("supplied","native-accession-alternative").contains(provenance))throw new IOException("Explicit supported RMA provenance required");
            Limits caps=limits(options);var modes=modes(options.get("--mode"));var parameters=parameters(options);
            Path runtime=Path.of(options.get("--runtime")).toAbsolutePath().normalize();
            var originals=new LinkedHashMap<String,Path>();for(String key:List.of("input","taxonomy","taxa"))originals.put(key,Path.of(options.get("--"+key)).toRealPath());
            out=Path.of(options.get("--out")).toAbsolutePath().normalize();if(overlap(out,runtime))throw new IOException("Output overlaps the original reader provider");for(Path path:originals.values())if(overlap(out,path))throw new IOException("Output overlaps an original input");
            if(Files.exists(out,LinkOption.NOFOLLOW_LINKS)||out.getParent()==null||!out.getParent().toRealPath().equals(out.getParent()))throw new IOException("Canonical NEW output directory required");
            var originalPins=new LinkedHashMap<String,NextflowFiles.Pin>();long total=0;for(var entry:originals.entrySet()){var pin=NextflowFiles.pin(entry.getValue(),caps.fileBytes(),()->{});originalPins.put(entry.getKey(),pin);total=Math.addExact(total,pin.bytes());}if(total>caps.inputBytes())throw new IOException("Complete inputs exceed total byte capacity");
            Files.createDirectory(out);owned=true;if(out.getFileSystem().supportedFileAttributeViews().contains("posix"))Files.setPosixFilePermissions(out,PosixFilePermissions.fromString("rwx------"));
            Path input=Files.createDirectory(out.resolve("inputs"));var members=Map.of("input","inputs/source.rma6","taxonomy","inputs/ncbi.tre","taxa","inputs/taxa.tsv");
            for(var entry:originals.entrySet()){Path captured=out.resolve(members.get(entry.getKey()));Files.copy(entry.getValue(),captured);if(!NextflowFiles.pin(captured,caps.fileBytes(),()->{}).equals(originalPins.get(entry.getKey())))throw new IOException("Captured complete input differs");}
            var audit=analyze(out,runtime,caps,modes,parameters,true);
            for(var entry:originals.entrySet())if(!NextflowFiles.pin(entry.getValue(),caps.fileBytes(),()->{}).equals(originalPins.get(entry.getKey())))throw new IOException("Original input changed during complete extraction");
            var report=new LinkedHashMap<String,Object>();report.put("status",STATUS);report.put("method",METHOD);report.put("mode",options.get("--mode"));report.put("input_provenance",provenance);report.put("capacities",caps.document());report.put("parameters",parameters);report.put("audit",audit);report.put("original_locations",originals);report.put("original_pins",originalPins);report.put("whole_tool_qualified",false);report.put("producer_authenticated",false);report.put("new_tool_credit",0);
            NextflowFiles.writeJson(out.resolve("audit.json"),report);Files.writeString(out.resolve("WARNINGS.md"),WARNING+"\nReader diagnostics:\n"+NextflowJson.json(audit.get("reader_warnings"))+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);
            NextflowFiles.writeJson(out.resolve("COMPONENT_COMPLETED.json"),Map.of("status",STATUS,"files",inventory(out,caps.fileBytes()),"new_tool_credit",0));
            console.println("CAPTURED_COMPLETE_NATIVE_MALTEXTRACT17_READ_PROJECTION_ONLY; read WARNINGS.md.\n"+ACTION);return 0;
        }catch(Exception exception){int code=exception instanceof MaltExtractRmaReader.MissingRuntimeException?3:2;error.println("MALTEXTRACT READS "+(code==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED":"FAIL2 NO RESULT ADMITTED")+": "+exception+"\n"+ACTION);if(owned&&out!=null)try{NextflowFiles.writeJson(out.resolve("FAILURE.json"),Map.of("status",code==3?"SKIP3":"FAIL2","error",exception.toString(),"required_action",ACTION));Files.writeString(out.resolve("WARNINGS_FAILURE.md"),"# "+(code==3?"SKIP3":"FAIL2")+" NO RESULT\n\n"+exception+"\n\n"+ACTION+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(IOException diagnostic){error.println("Diagnostic write failed: "+diagnostic);}return code;}
    }
    private static Map<String,Object> analyze(Path root,Path runtime,Limits caps,List<MaltExtractReadProjection.Mode> modes,Map<String,Object> parameters,boolean write)throws IOException {
        long bytes=0;for(String member:List.of("inputs/source.rma6","inputs/ncbi.tre","inputs/taxa.tsv"))bytes=Math.addExact(bytes,NextflowFiles.pin(root.resolve(member),caps.fileBytes(),()->{}).bytes());if(bytes>caps.inputBytes())throw new IOException("Complete saved input set exceeds declared total byte capacity");
        List<Integer> ids=taxa(root.resolve("inputs/taxa.tsv"),caps.taxa());MaltExtractTaxonomy tree;
        try(var reader=Files.newBufferedReader(root.resolve("inputs/ncbi.tre"))){tree=MaltExtractTaxonomy.read(reader,new MaltExtractTaxonomy.Limits(Math.min(caps.fileBytes(),100000000),3000000,1024));}
        for(int id:ids)if(!tree.contains(id))throw new IOException("Explicit stored taxon is not in the supplied complete numeric taxonomy: "+id);
        var rows=new ArrayList<MaltExtractRmaReader.Read>();var reader=MaltExtractRmaReader.read(runtime,root.resolve("inputs/source.rma6"),caps.reader(),MaltExtractRmaReader.EXTRACTION,rows::add);
        var results=new ArrayList<Map<String,Object>>();var projectionPins=new TreeMap<String,NextflowFiles.Pin>();
        for(var mode:modes) {
            Path directory=root.resolve("derived/"+mode.name().toLowerCase(Locale.ROOT));if(write)Files.createDirectories(directory);
            var p=projectionOptions(mode,parameters);
            for(int id:ids) {
                var result=MaltExtractReadProjection.project(rows,id,p);var fasta=new StringBuilder();for(var pair:result.reads()){if(pair.header().indexOf('\n')>=0||pair.header().indexOf('\r')>=0||pair.sequence().indexOf('\n')>=0||pair.sequence().indexOf('\r')>=0)throw new IOException("Literal read fields contain line separators; do not silently repair identities or sequences");fasta.append(pair.header()).append('\n').append(pair.sequence()).append('\n');}
                byte[] data=fasta.toString().getBytes(StandardCharsets.UTF_8);if(data.length>caps.fileBytes())throw new IOException("Complete projected FASTA exceeds file capacity");Path target=directory.resolve(id+".fasta");if(write)Files.write(target,data,StandardOpenOption.CREATE_NEW);else if(!Arrays.equals(NextflowFiles.bytes(target,Math.toIntExact(Math.min(caps.fileBytes(),Integer.MAX_VALUE))),data))throw new IOException("Saved complete native FASTA projection differs: "+target);
                String name=root.relativize(target).toString().replace('\\','/');projectionPins.put(name,new NextflowFiles.Pin(data.length,NextflowFiles.sha(data)));
                results.add(Map.of("taxon",id,"mode",mode.name(),"assigned",result.assigned(),"sequence_eligible",result.sequenceEligible(),"considered_matches",result.consideredMatches(),"retained_matches",result.retainedMatches(),"projected_reads",result.reads().size(),"fasta",name));
            }
        }
        var classes=new ArrayList<Map<String,Object>>();for(var entry:reader.classifications().values())classes.add(Map.of("taxon",entry.taxon(),"reads",entry.reads(),"weighted_reads_float_bits",Integer.toHexString(Float.floatToRawIntBits(entry.weightedReads()))));
        var audit=new LinkedHashMap<String,Object>();audit.put("input",Map.of("bytes",reader.input().bytes(),"sha256",reader.input().sha256()));audit.put("program",Map.of("bytes",reader.program().bytes(),"sha256",reader.program().sha256()));audit.put("profile",Map.of("minimum_score",1,"maximum_expected",100,"sequence",true));audit.put("stored_reads",reader.reads());audit.put("stored_matches",reader.storedMatches());audit.put("available_matches",reader.availableMatches());audit.put("classes",classes);audit.put("taxonomy_nodes",tree.size());audit.put("taxonomy_explicit_branch_lengths",tree.explicitLengths());audit.put("taxa",ids);audit.put("projections",results);audit.put("projection_pins",projectionPins);audit.put("reader_warnings",reader.warnings());return audit;
    }
    private static List<Integer> taxa(Path path,int maximum)throws IOException {
        if(Files.size(path)>1048576)throw new IOException("Complete taxon list exceeds1MiB capacity");var lines=Files.readAllLines(path,StandardCharsets.UTF_8);if(lines.isEmpty()||!lines.get(0).equals("taxon_id")||lines.size()<2||lines.size()-1>maximum)throw new IOException("Require the complete one-column taxon_id list within capacity");var ids=new ArrayList<Integer>();var seen=new HashSet<Integer>();for(int i=1;i<lines.size();i++){String line=lines.get(i);if(!line.matches("[1-9][0-9]*"))throw new IOException("Require literal positive decimal taxon IDs without trimming or alias repair");int id=Integer.parseInt(line);if(!seen.add(id))throw new IOException("Repeated stored taxon ID");ids.add(id);}return List.copyOf(ids);
    }
    private static List<MaltExtractReadProjection.Mode> modes(String mode)throws IOException {
        return switch(mode){case "default"->List.of(MaltExtractReadProjection.Mode.DEFAULT);case "ancient"->List.of(MaltExtractReadProjection.Mode.ANCIENT);case "both"->List.of(MaltExtractReadProjection.Mode.DEFAULT,MaltExtractReadProjection.Mode.ANCIENT);default->throw new IOException("Explicit default, ancient or both mode required");};
    }
    private static Map<String,Object> parameters(Map<String,String> options)throws IOException {
        var result=new LinkedHashMap<String,Object>();result.put("top_fraction",decimal(options.getOrDefault("--top-fraction","0.01"),0,1));result.put("minimum_identity_percent",decimal(options.getOrDefault("--minimum-identity-percent","0"),0,100));result.put("maximum_read_length",number(options,"--maximum-read-length",0,0,Integer.MAX_VALUE));result.put("minimum_complexity",decimal(options.getOrDefault("--minimum-complexity","0"),0,1));result.put("top_alignment_only",bool(options.getOrDefault("--top-alignment-only","false")));result.put("single_stranded",bool(options.getOrDefault("--single-stranded","false")));return result;
    }
    private static MaltExtractReadProjection.Options projectionOptions(MaltExtractReadProjection.Mode mode,Map<String,Object> p)throws IOException {
        return new MaltExtractReadProjection.Options(mode,decimal(String.valueOf(p.get("top_fraction")),0,1),decimal(String.valueOf(p.get("minimum_identity_percent")),0,100),(int)NextflowFiles.integer(p.get("maximum_read_length"),0,Integer.MAX_VALUE),decimal(String.valueOf(p.get("minimum_complexity")),0,1),bool(String.valueOf(p.get("top_alignment_only"))),bool(String.valueOf(p.get("single_stranded"))));
    }
    private static boolean bool(String value)throws IOException {if(!Set.of("true","false").contains(value))throw new IOException("Literal true or false required");return value.equals("true");}
    private static double decimal(String value,double min,double max)throws IOException {double number=Double.parseDouble(value);if(!Double.isFinite(number)||number<min||number>max)throw new IOException("Finite explicit parameter outside supported source-profile range");return number;}
    private static long number(Map<String,String> options,String key,long fallback,long min,long max)throws IOException {long n=Long.parseLong(options.getOrDefault(key,Long.toString(fallback)));if(n<min||n>max)throw new IOException("Capacity outside supported range: "+key);return n;}
    private static Limits limits(Map<String,String> o)throws IOException {return new Limits(number(o,"--maximum-file-bytes",1000000000,1,Integer.MAX_VALUE),number(o,"--maximum-input-bytes",4000000000L,1,500000000000L),(int)number(o,"--maximum-reads",1000000,1,Integer.MAX_VALUE),number(o,"--maximum-matches",10000000,1,100000000000L),(int)number(o,"--maximum-matches-per-read",100000,1,Integer.MAX_VALUE),(int)number(o,"--maximum-text-characters",1000000,1,Integer.MAX_VALUE),(int)number(o,"--maximum-taxa",1000,1,4000));}
    private static boolean overlap(Path a,Path b){return a.startsWith(b)||b.startsWith(a);}
    private static Map<String,NextflowFiles.Pin> inventory(Path root,long maximum)throws IOException {
        var files=new TreeMap<String,NextflowFiles.Pin>();try(var paths=Files.walk(root)){for(Path p:paths.filter(p->!Files.isDirectory(p,LinkOption.NOFOLLOW_LINKS)).toList()){if(files.size()>=10000)throw new IOException("Complete bundle exceeds file capacity");String name=NextflowFiles.member(root.relativize(p).toString().replace('\\','/'));if(!name.equals("COMPONENT_COMPLETED.json"))files.put(name,NextflowFiles.pin(p,maximum,()->{}));}}return files;
    }
    private static void verify(Path root,Path runtime)throws IOException {
        NextflowFiles.directory(root);if(Files.exists(root.resolve("FAILURE.json"))||Files.exists(root.resolve("WARNINGS_FAILURE.md")))throw new IOException("A failed/provisional extraction is not a completed bundle");
        var complete=NextflowFiles.object(NextflowFiles.json(root.resolve("COMPONENT_COMPLETED.json"),16777216));NextflowFiles.keys(complete,"status","files","new_tool_credit");if(!STATUS.equals(complete.get("status"))||NextflowFiles.integer(complete.get("new_tool_credit"),0,0)!=0)throw new IOException("Unsupported saved extraction scope");
        var report=NextflowFiles.object(NextflowFiles.json(root.resolve("audit.json"),16777216));if(!STATUS.equals(report.get("status"))||!METHOD.equals(report.get("method"))||!Boolean.FALSE.equals(report.get("whole_tool_qualified"))||!Boolean.FALSE.equals(report.get("producer_authenticated"))||NextflowFiles.integer(report.get("new_tool_credit"),0,0)!=0||!Set.of("supplied","native-accession-alternative").contains(report.get("input_provenance")))throw new IOException("Unsupported saved method, provenance or result claim");
        var c=NextflowFiles.object(report.get("capacities"));NextflowFiles.keys(c,"file_bytes","input_bytes","reads","matches","matches_per_read","text_characters","taxa");
        Limits caps=new Limits(NextflowFiles.integer(c.get("file_bytes"),1,Integer.MAX_VALUE),NextflowFiles.integer(c.get("input_bytes"),1,500000000000L),(int)NextflowFiles.integer(c.get("reads"),1,Integer.MAX_VALUE),NextflowFiles.integer(c.get("matches"),1,100000000000L),(int)NextflowFiles.integer(c.get("matches_per_read"),1,Integer.MAX_VALUE),(int)NextflowFiles.integer(c.get("text_characters"),1,Integer.MAX_VALUE),(int)NextflowFiles.integer(c.get("taxa"),1,4000));
        var expected=new TreeMap<String,NextflowFiles.Pin>();for(var entry:NextflowFiles.object(complete.get("files")).entrySet())expected.put(NextflowFiles.member(NextflowFiles.text(entry.getKey())),NextflowFiles.fingerprint(entry.getValue(),caps.fileBytes()));if(!inventory(root,caps.fileBytes()).equals(expected))throw new IOException("Complete saved bundle inventory differs");
        var originalPins=NextflowFiles.object(report.get("original_pins"));NextflowFiles.keys(originalPins,"input","taxonomy","taxa");for(var binding:Map.of("input","inputs/source.rma6","taxonomy","inputs/ncbi.tre","taxa","inputs/taxa.tsv").entrySet())if(!NextflowFiles.fingerprint(originalPins.get(binding.getKey()),caps.fileBytes()).equals(expected.get(binding.getValue())))throw new IOException("Captured input differs from declared original pin");
        var p=new LinkedHashMap<String,Object>();for(var entry:NextflowFiles.object(report.get("parameters")).entrySet())p.put(NextflowFiles.text(entry.getKey()),entry.getValue());NextflowFiles.keys(p,"top_fraction","minimum_identity_percent","maximum_read_length","minimum_complexity","top_alignment_only","single_stranded");
        var audit=analyze(root,runtime,caps,modes(NextflowFiles.text(report.get("mode"))),p,false);if(!NextflowJson.json(audit).equals(NextflowJson.json(report.get("audit"))))throw new IOException("Complete saved native projection audit differs");if(!inventory(root,caps.fileBytes()).equals(expected))throw new IOException("Bundle changed during saved verification");
    }
}
